import Foundation

/// Silhouettes of the 6 Plato chess pieces (P N B R Q K), 24×24 coverage grids, little-endian Float32.
enum PlatoChessData {
    static let shapes: [Float] = {
        let d = Data(base64Encoded: b64)!
        return d.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
    }()
    private static let b64 = ""
}
